import React, { useState } from 'react';
import type { Event, TrainingModule } from '../types';
import { Badge } from '../components/ui/Badge';
import { MediaGallery } from '../components/MediaGallery';
import { SourceList } from '../components/SourceList';
import { useFavorites } from '../hooks/useFavorites';
import { StarIcon } from '../components/icons/StarIcon';
import { ShareIcon } from '../components/icons/ShareIcon';
import { DownloadIcon } from '../components/icons/DownloadIcon';
import { ArrowLeftIcon } from '../components/icons/ArrowLeftIcon';
import { GraduationCapIcon } from '../components/icons/GraduationCapIcon';
import { TimelineIcon } from '../components/icons/TimelineIcon';
import { generatePdf } from '../utils/pdfGenerator';
import { formatDate } from '../utils/helpers';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from '../components/ui/Dialog';
import { Button } from '../components/ui/Button';
import { Card, CardContent } from '../components/ui/Card';


type View = 'home' | 'calendar' | 'favorites' | 'event' | 'timeline' | 'module';

interface EventDetailPageProps {
  event: Event;
  onBack: () => void;
  fromView: View;
  navigateToModule: (slug: string) => void;
  navigateToTimeline?: (slug: string) => void;
}

const ModuleChooserDialog: React.FC<{
    isOpen: boolean;
    onOpenChange: (isOpen: boolean) => void;
    modules: TrainingModule[];
    onSelectModule: (slug: string) => void;
}> = ({ isOpen, onOpenChange, modules, onSelectModule }) => {

    const handleStartModule = (module: TrainingModule) => {
        onSelectModule(module.slug);
        onOpenChange(false);
    };

    return (
        <Dialog open={isOpen} onOpenChange={onOpenChange}>
            <DialogContent>
                <DialogHeader>
                    <DialogTitle>Choose a module</DialogTitle>
                    <DialogDescription>
                        This event has multiple training modules available.
                    </DialogDescription>
                </DialogHeader>
                <div className="space-y-3 py-4">
                    {modules.map(m => (
                        <Card key={m.id} className="rounded-2xl">
                            <CardContent className="p-4 flex items-center justify-between">
                                <div>
                                    <p className="font-semibold">{m.title}</p>
                                    <p className="text-sm text-muted-foreground">
                                        {m.level ?? ""}{m.durationMin ? ` • ${m.durationMin} min` : ""}
                                    </p>
                                </div>
                                <Button onClick={() => handleStartModule(m)} size="sm">Start</Button>
                            </CardContent>
                        </Card>
                    ))}
                </div>
            </DialogContent>
        </Dialog>
    )
}


export const EventDetailPage: React.FC<EventDetailPageProps> = ({ event, onBack, fromView, navigateToModule, navigateToTimeline }) => {
  const { exists, toggle } = useFavorites();
  const [isModuleDialogOpen, setIsModuleDialogOpen] = useState(false);
  const isFav = exists('event', event.id);

  const handleToggleFavorite = () => {
    toggle({
      type: 'event',
      id: event.id,
      slug: event.slug,
      title: event.title,
      thumbnail: event.media[0]?.url,
    });
  };

  const handleShare = () => {
    navigator.clipboard.writeText(window.location.href);
    alert('Link copied to clipboard!');
  };

  const handleDownload = () => {
    generatePdf(event);
  }

  const handleOpenModule = () => {
      if (!event.trainingModules) return;
      if (event.trainingModules.length === 1) {
          navigateToModule(event.trainingModules[0].slug);
      } else if (event.trainingModules.length > 1) {
          setIsModuleDialogOpen(true);
      }
  };

  const handleViewTimeline = () => {
      if (event.timelineSlug && navigateToTimeline) {
          navigateToTimeline(event.timelineSlug);
      }
  };

  const backButtonText: Record<View, string> = {
    home: 'Back to Discover',
    calendar: 'Back to Calendar',
    favorites: 'Back to Saved Items',
    timeline: 'Back to Timeline',
    event: 'Back', // Fallback
    module: 'Back', // Fallback
  };

  return (
    <div className="max-w-4xl mx-auto">
      <button onClick={onBack} className="flex items-center gap-2 text-sm text-primary mb-6 hover:underline">
        <ArrowLeftIcon className="h-4 w-4" />
        {backButtonText[fromView] || 'Back'}
      </button>

      <article className="bg-card p-6 sm:p-8 rounded-2xl shadow-soft">
        <header className="mb-6">
          <div className="flex flex-wrap items-center gap-2 mb-2 text-sm text-muted-foreground">
            <span>{event.dateISO ? formatDate(new Date(event.dateISO)) : event.period}</span>
            {event.countryCode && <><span>&middot;</span><span>{event.countryCode}</span></>}
          </div>
          <h1 className="text-3xl sm:text-4xl font-bold text-secondary">{event.title}</h1>
          <div className="flex flex-wrap gap-2 mt-4">
            {event.themes.map(theme => (
              <Badge key={theme.id} variant="secondary">{theme.name}</Badge>
            ))}
          </div>
        </header>

        <MediaGallery media={event.media} />

        <div className="prose max-w-none mt-6 text-dark/90">
          <p className="text-lg leading-relaxed">{event.summary}</p>
        </div>

        {event.timelineSlug && (
          <div className="mt-8 p-6 rounded-2xl bg-primary/5 border border-primary/10 flex flex-col md:flex-row items-center justify-between gap-4">
            <div className="space-y-1">
              <h4 className="font-bold text-primary flex items-center gap-2">
                <TimelineIcon className="h-5 w-5" />
                Narration temporelle
              </h4>
              <p className="text-sm text-muted-foreground">Cet événement fait partie d'une fresque historique complète.</p>
            </div>
            <Button onClick={handleViewTimeline} className="rounded-full px-6 shadow-md hover:scale-105 transition-transform">
               Explorer la timeline
            </Button>
          </div>
        )}

        <div className="mt-8 border-t pt-6">
          <h3 className="text-xl font-semibold mb-3 text-secondary">Sources</h3>
          <SourceList sources={event.sources} />
        </div>

        <div className="mt-8 pt-6 border-t flex flex-col sm:flex-row items-center justify-between gap-4">
            <div>
                {event.trainingModules && event.trainingModules.length > 0 && (
                    <Button
                        onClick={handleOpenModule}
                        aria-label={`Ouvrir le module de formation lié à ${event.title}`}
                        className="rounded-2xl shadow-sm w-full sm:w-auto bg-secondary text-secondary-foreground hover:bg-secondary/90"
                    >
                        <GraduationCapIcon className="mr-2 h-4 w-4" />
                        🎓 Découvrir le module
                    </Button>
                )}
            </div>
            <div className="flex items-center justify-end gap-2">
                <Button onClick={handleToggleFavorite} variant={isFav ? 'secondary' : 'outline'} aria-pressed={isFav} className="w-full sm:w-auto">
                    <StarIcon className={`mr-2 h-4 w-4 ${isFav ? 'fill-current' : ''}`} />
                    {isFav ? '★ Saved' : '☆ Save'}
                </Button>
                <button onClick={handleShare} className="flex items-center gap-2 px-4 py-2 border rounded-md text-sm font-medium hover:bg-muted transition-colors">
                    <ShareIcon className="h-4 w-4" />
                    Share
                </button>
                <button onClick={handleDownload} className="flex items-center gap-2 px-4 py-2 border rounded-md text-sm font-medium bg-primary text-primary-foreground hover:bg-primary/90 transition-colors">
                    <DownloadIcon className="h-4 w-4" />
                    Download PDF
                </button>
            </div>
        </div>
      </article>

      {event.trainingModules && event.trainingModules.length > 1 && (
        <ModuleChooserDialog 
            isOpen={isModuleDialogOpen}
            onOpenChange={setIsModuleDialogOpen}
            modules={event.trainingModules}
            onSelectModule={navigateToModule}
        />
      )}
    </div>
  );
};

import React, { useState, useEffect, useMemo, useRef } from 'react';
import type { Event } from '../types';
import { getEvents } from '../services/api';
import { formatDate } from '../utils/helpers';
import { THEME_COLORS } from '../constants';
import { Badge } from '../components/ui/Badge';
import { ArrowLeftIcon } from '../components/icons/ArrowLeftIcon';
import { ChevronLeftIcon } from '../components/icons/ChevronLeftIcon';
import { ChevronRightIcon } from '../components/icons/ChevronRightIcon';

interface TimelinePageProps {
  onViewEvent: (event: Event) => void;
  timelineSlug?: string | null;
  onBack?: () => void;
}

const getYearFromEvent = (event: Event): number => {
    if (event.year) return event.year;
    if (event.dateISO) return new Date(event.dateISO).getFullYear();
    if (event.period) {
        const match = event.period.match(/\d{4}/);
        if (match) return parseInt(match[0], 10);
    }
    return 9999;
};

const TimelineCard: React.FC<{ 
    event: Event; 
    isActive: boolean; 
    isPrev: boolean; 
    isNext: boolean;
    onClick: () => void;
}> = ({ event, isActive, isPrev, isNext, onClick }) => {

    const cardClass = useMemo(() => {
        if (isActive) return "scale-100 opacity-100 z-30 shadow-2xl translate-x-0";
        if (isPrev) return "scale-90 opacity-40 blur-[2px] -translate-x-full z-10 hidden md:flex";
        if (isNext) return "scale-90 opacity-40 blur-[2px] translate-x-full z-10 hidden md:flex";
        return "scale-75 opacity-0 pointer-events-none hidden";
    }, [isActive, isPrev, isNext]);

    return (
        <div 
            onClick={onClick}
            className={`absolute inset-0 m-auto w-full max-w-[320px] sm:max-w-md h-[450px] sm:h-[500px] transition-all duration-500 ease-out cursor-pointer flex flex-col rounded-3xl overflow-hidden border border-white/30 backdrop-blur-2xl bg-white/40 ${cardClass}`}
        >
            <div className="h-2/5 w-full relative">
                <img 
                    src={event.media[0]?.url || 'https://picsum.photos/400/400'} 
                    alt={event.title}
                    className="w-full h-full object-cover"
                />
                <div className="absolute top-4 left-4">
                    <span className="px-3 py-1 bg-white/20 backdrop-blur-md rounded-full text-xs font-bold text-white border border-white/20">
                        {event.dateISO ? formatDate(new Date(event.dateISO)) : (event.period || event.year)}
                    </span>
                </div>
            </div>
            <div className="flex-1 p-6 flex flex-col justify-between">
                <div>
                    <h3 className="text-xl sm:text-2xl font-bold text-secondary leading-tight mb-3">
                        {event.title}
                    </h3>
                    <p className="text-sm sm:text-base text-dark/70 line-clamp-4 leading-relaxed">
                        {event.summary}
                    </p>
                </div>
                <div className="flex flex-wrap gap-2 mt-4">
                    {event.themes.map(t => (
                        <Badge key={t.id} style={{ backgroundColor: THEME_COLORS[t.slug], color: '#fff', border: 'none' }}>
                            {t.name}
                        </Badge>
                    ))}
                </div>
            </div>
        </div>
    );
};

export const TimelinePage: React.FC<TimelinePageProps> = ({ onViewEvent, timelineSlug, onBack }) => {
    const [events, setEvents] = useState<Event[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [activeIndex, setActiveIndex] = useState(0);
    const containerRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const fetchEvents = async () => {
            setIsLoading(true);
            const allEvents = await getEvents();
            let filtered = allEvents;
            if (timelineSlug) {
                filtered = allEvents.filter(e => e.timelineSlug === timelineSlug);
            }
            const sorted = filtered.sort((a, b) => getYearFromEvent(a) - getYearFromEvent(b));
            setEvents(sorted);
            setIsLoading(false);
        };
        fetchEvents();
    }, [timelineSlug]);

    const goNext = () => setActiveIndex(prev => Math.min(prev + 1, events.length - 1));
    const goPrev = () => setActiveIndex(prev => Math.max(prev - 1, 0));

    // Support Swipe
    const touchStart = useRef<number | null>(null);
    const handleTouchStart = (e: React.TouchEvent) => touchStart.current = e.touches[0].clientX;
    const handleTouchEnd = (e: React.TouchEvent) => {
        if (!touchStart.current) return;
        const diff = touchStart.current - e.changedTouches[0].clientX;
        if (diff > 50) goNext();
        if (diff < -50) goPrev();
        touchStart.current = null;
    };

    if (isLoading) {
        return (
            <div className="h-[60vh] flex items-center justify-center">
                <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary"></div>
            </div>
        );
    }

    if (events.length === 0) {
        return (
            <div className="p-8 text-center">
                <p className="text-muted-foreground">Aucune timeline trouvée pour cette narration.</p>
                {onBack && <Button onClick={onBack} className="mt-4">Retour</Button>}
            </div>
        );
    }

    return (
        <div className="fixed inset-0 z-50 bg-[#FAF8F5] md:relative md:inset-auto md:bg-transparent overflow-hidden flex flex-col h-screen md:h-auto">
            {/* Header / Nav */}
            <div className="p-4 md:p-0 flex items-center justify-between mb-4">
                <button 
                    onClick={onBack} 
                    className="p-2 bg-white/80 backdrop-blur-md rounded-full shadow-sm hover:bg-white transition-colors"
                >
                    <ArrowLeftIcon className="h-5 w-5" />
                </button>
                <div className="text-center flex-1 mx-4">
                    <h1 className="text-lg font-bold text-secondary line-clamp-1">
                        {timelineSlug ? "Frise Narrative" : "L'Histoire en marche"}
                    </h1>
                    <p className="text-xs text-muted-foreground">
                        {activeIndex + 1} sur {events.length} moments clés
                    </p>
                </div>
                <div className="w-10"></div>
            </div>

            {/* Immersion Background Effect */}
            <div className="absolute inset-0 pointer-events-none opacity-20 overflow-hidden">
                <div 
                    className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[800px] h-[800px] rounded-full blur-[120px]"
                    style={{ backgroundColor: THEME_COLORS[events[activeIndex].themes[0]?.slug] || '#E67E22' }}
                ></div>
            </div>

            {/* Carousel Area */}
            <div 
                className="flex-1 relative flex items-center justify-center py-8"
                onTouchStart={handleTouchStart}
                onTouchEnd={handleTouchEnd}
            >
                {/* Navigation Buttons (Desktop) */}
                <button 
                    onClick={goPrev} 
                    disabled={activeIndex === 0}
                    className="absolute left-4 z-40 p-3 rounded-full bg-white/60 backdrop-blur-lg border border-white/40 shadow-lg disabled:opacity-20 hidden md:block"
                >
                    <ChevronLeftIcon className="h-6 w-6 text-secondary" />
                </button>
                <button 
                    onClick={goNext} 
                    disabled={activeIndex === events.length - 1}
                    className="absolute right-4 z-40 p-3 rounded-full bg-white/60 backdrop-blur-lg border border-white/40 shadow-lg disabled:opacity-20 hidden md:block"
                >
                    <ChevronRightIcon className="h-6 w-6 text-secondary" />
                </button>

                {/* Cards Container */}
                <div className="relative w-full h-full max-w-5xl mx-auto flex items-center justify-center px-4">
                    {events.map((event, idx) => (
                        <TimelineCard 
                            key={event.id}
                            event={event}
                            isActive={idx === activeIndex}
                            isPrev={idx === activeIndex - 1}
                            isNext={idx === activeIndex + 1}
                            onClick={() => {
                                if (idx === activeIndex - 1) goPrev();
                                if (idx === activeIndex + 1) goNext();
                                if (idx === activeIndex) onViewEvent(event);
                            }}
                        />
                    ))}
                </div>
            </div>

            {/* Progress Visualizer (Footer) */}
            <div className="p-8 space-y-4">
                <div className="relative h-1 w-full bg-border/30 rounded-full max-w-2xl mx-auto">
                    <div 
                        className="absolute top-0 left-0 h-full bg-primary transition-all duration-500 rounded-full"
                        style={{ width: `${((activeIndex + 1) / events.length) * 100}%` }}
                    ></div>
                    {/* Tick marks */}
                    <div className="absolute inset-0 flex justify-between px-0.5 pointer-events-none">
                        {events.map((_, i) => (
                            <div key={i} className={`h-1 w-1 rounded-full ${i <= activeIndex ? 'bg-primary' : 'bg-border/50'}`}></div>
                        ))}
                    </div>
                </div>
                <div className="flex justify-between items-center max-w-2xl mx-auto px-1">
                    <span className="text-[10px] font-bold text-muted-foreground uppercase tracking-wider">
                        Début : {getYearFromEvent(events[0])}
                    </span>
                    <span className="text-[10px] font-bold text-muted-foreground uppercase tracking-wider">
                        Fin : {getYearFromEvent(events[events.length-1])}
                    </span>
                </div>
            </div>
        </div>
    );
};

import React, { useState, useCallback, useRef, useEffect } from 'react';
import { Layout } from './components/Layout';
import { HomePage } from './pages/HomePage';
import { CalendarPage } from './pages/CalendarPage';
import { FavoritesPage } from './pages/FavoritesPage';
import { EventDetailPage } from './pages/EventDetailPage';
import { TimelinePage } from './pages/TimelinePage';
import { ModulePage } from './pages/ModulePage';
import { ModulesIndexPage } from './pages/ModulesIndexPage';
import { AdminLoginPage } from './pages/admin/AdminLoginPage';
import { AdminDashboardPage } from './pages/admin/AdminDashboardPage';
import { AdminEventsPage } from './pages/admin/AdminEventsPage';
import { AdminModulesPage } from './pages/admin/AdminModulesPage';
import { AdminThemesPage } from './pages/admin/AdminThemesPage';
import { AdminFeaturedPage } from './pages/admin/AdminFeaturedPage';
import { EventFormPage } from './pages/admin/forms/EventFormPage';
import { ModuleFormPage } from './pages/admin/forms/ModuleFormPage';
import { ThemeFormPage } from './pages/admin/forms/ThemeFormPage';
import { FeaturedFormPage } from './pages/admin/forms/FeaturedFormPage';
import { AuthProvider, useAuth } from './hooks/useAuth';
import type { Event, TrainingModule } from './types';
import { EVENTS, ALL_TRAINING_MODULES } from './constants';
// Moodle Admin Pages
import { AdminMoodleInstancesPage } from './pages/admin/moodle/AdminMoodleInstancesPage';
import { AdminMoodleCoursesPage } from './pages/admin/moodle/AdminMoodleCoursesPage';
import { AdminMoodlePackagesPage } from './pages/admin/moodle/AdminMoodlePackagesPage';
import { AdminMoodleMapsPage } from './pages/admin/moodle/AdminMoodleMapsPage';
import { MoodleInstanceFormPage } from './pages/admin/moodle/forms/MoodleInstanceFormPage';
import { MoodleCourseFormPage } from './pages/admin/moodle/forms/MoodleCourseFormPage';
import { MoodlePackageFormPage } from './pages/admin/moodle/forms/MoodlePackageFormPage';
import { MoodleMapFormPage } from './pages/admin/moodle/forms/MoodleMapFormPage';
import { MoodlePackageUploadPage } from './pages/admin/moodle/forms/MoodlePackageUploadPage';
// Offline Player Pages
import { ScormPlayerPage } from './pages/offline/ScormPlayerPage';
import { H5pPlayerPage } from './pages/offline/H5pPlayerPage';


type View = 'home' | 'calendar' | 'favorites' | 'event' | 'timeline' | 'module' | 'modules' | 
            'adminLogin' | 'adminDashboard' | 'adminEvents' | 'adminModules' | 'adminThemes' |
            'adminNewEvent' | 'adminEditEvent' | 'adminNewModule' | 'adminEditModule' |
            'adminNewTheme' | 'adminEditTheme' | 'adminFeatured' | 'adminNewFeatured' | 'adminEditFeatured' |
            'adminMoodleInstances' | 'adminNewMoodleInstance' | 'adminEditMoodleInstance' |
            'adminMoodleCourses' | 'adminNewMoodleCourse' | 'adminEditMoodleCourse' |
            'adminMoodlePackages' | 'adminNewMoodlePackage' | 'adminEditMoodlePackage' | 'adminMoodlePackageUpload' |
            'adminMoodleMaps' | 'adminNewMoodleMap' | 'adminEditMoodleMap' |
            'offlineScorm' | 'offlineH5p';

const AppContent: React.FC = () => {
  const [view, setView] = useState<View>('calendar');
  const [previousView, setPreviousView] = useState<View | null>(null);
  const [selectedEvent, setSelectedEvent] = useState<Event | null>(null);
  const [selectedModule, setSelectedModule] = useState<TrainingModule | null>(null);
  const [selectedItemId, setSelectedItemId] = useState<string | null>(null);
  const [selectedTimelineSlug, setSelectedTimelineSlug] = useState<string | null>(null);
  const [scrollTargetId, setScrollTargetId] = useState<string | null>(null);
  const scrollPositions = useRef<Partial<Record<View, number>>>({});
  const { session } = useAuth();

  const navigateTo = useCallback((newView: View, id?: string) => {
    if (view !== newView || (id && id !== selectedItemId)) {
      scrollPositions.current[view] = window.scrollY;
      setScrollTargetId(null);
      setPreviousView(view);
      setView(newView);
      setSelectedItemId(id ?? null);
      window.scrollTo(0, 0);
    }
  }, [view, selectedItemId]);

  const viewEvent = useCallback((event: Event) => {
    scrollPositions.current[view] = window.scrollY;
    setScrollTargetId(event.id); 
    setPreviousView(view);
    setSelectedEvent(event);
    setView('event');
    window.scrollTo(0, 0);
  }, [view]);

  const navigateToTimeline = useCallback((slug: string) => {
      scrollPositions.current[view] = window.scrollY;
      setPreviousView(view);
      setSelectedTimelineSlug(slug);
      setView('timeline');
      window.scrollTo(0, 0);
  }, [view]);

  const navigateToModule = useCallback((moduleSlug: string) => {
      const module = ALL_TRAINING_MODULES.find(m => m.slug === moduleSlug);

      if (module) {
          scrollPositions.current[view] = window.scrollY;
          setPreviousView(view);
          setSelectedModule(module);
          setView('module');
          window.scrollTo(0, 0);
      } else {
          console.error(`Module with slug ${moduleSlug} not found.`);
      }
  }, [view]);

  const navigateToEventBySlug = useCallback((slug: string) => {
    const event = EVENTS.find(e => e.slug === slug);
    if (event) {
        viewEvent(event);
    } else {
        console.error(`Event with slug ${slug} not found.`);
    }
  }, [viewEvent]);


  const navigateBack = useCallback(() => {
    if (previousView) {
      setView(previousView);
      if(previousView === 'module') {
        setPreviousView('modules');
      }
    }
  }, [previousView]);

  useEffect(() => {
    if ((previousView === 'event' || previousView === 'module' || previousView === 'timeline') && scrollTargetId) {
      return;
    }

    const savedPosition = scrollPositions.current[view];
    if (typeof savedPosition === 'number') {
      setTimeout(() => window.scrollTo({ top: savedPosition, behavior: 'auto' }), 0);
    }
  }, [view, previousView, scrollTargetId]);

  // Effect to redirect if not authorized for admin pages
  useEffect(() => {
    const userRole = session?.user?.role;
    const isAuthorizedAdmin = userRole === 'SUPERADMIN' || userRole === 'EDITOR';
    if (view.startsWith('admin') && view !== 'adminLogin' && !isAuthorizedAdmin) {
      setView('adminLogin');
    }
  }, [view, session]);


  const onScrolled = useCallback(() => {
    setScrollTargetId(null);
  }, []);

  const renderView = () => {
    const userRole = session?.user?.role;
    const isAuthorizedAdmin = userRole === 'SUPERADMIN' || userRole === 'EDITOR';

    // Admin View Protection
    if (view.startsWith('admin') && view !== 'adminLogin' && !isAuthorizedAdmin) {
        return <AdminLoginPage navigateTo={navigateTo} />;
    }

    const shouldScrollToId = (previousView === 'event' || previousView === 'module') ? scrollTargetId : null;

    const viewEventById = (eventId: string) => {
        const event = EVENTS.find(e => e.id === eventId);
        if (event) {
            viewEvent(event);
        } else {
            console.error(`Event with ID ${eventId} not found.`);
        }
    };

    switch (view) {
      // Public views
      case 'home':
        return <HomePage onViewEvent={viewEvent} navigateToModule={navigateToModule}/>;
      case 'calendar':
        return <CalendarPage onViewEvent={viewEvent} navigateToModule={navigateToModule} navigateToEventBySlug={navigateToEventBySlug} />;
      case 'timeline':
        return <TimelinePage onViewEvent={viewEvent} timelineSlug={selectedTimelineSlug} onBack={navigateBack} />;
      case 'favorites':
        return <FavoritesPage onViewEvent={viewEvent} navigateToModule={navigateToModule} />;
      case 'modules':
        return <ModulesIndexPage navigateToModule={navigateToModule} />;
      case 'event':
        return selectedEvent ? <EventDetailPage event={selectedEvent} onBack={navigateBack} fromView={previousView || 'home'} navigateToModule={navigateToModule} navigateToTimeline={navigateToTimeline} /> : <HomePage onViewEvent={viewEvent} navigateToModule={navigateToModule} />;
      case 'module':
        return selectedModule ? <ModulePage module={selectedModule} onNavigateToEvent={viewEventById} onBack={navigateBack} navigateTo={navigateTo} /> : <HomePage onViewEvent={viewEvent} navigateToModule={navigateToModule} />;

      // Admin views
      case 'adminLogin':
        return <AdminLoginPage navigateTo={navigateTo} />;
      case 'adminDashboard':
        return <AdminDashboardPage navigateTo={navigateTo as any} />;
      case 'adminEvents':
          return <AdminEventsPage navigateTo={navigateTo as any}/>;
      case 'adminModules':
          return <AdminModulesPage navigateTo={navigateTo as any}/>;
      case 'adminThemes':
          return <AdminThemesPage navigateTo={navigateTo as any}/>;
      case 'adminFeatured':
          return <AdminFeaturedPage navigateTo={navigateTo as any}/>;
      case 'adminNewEvent':
          return <EventFormPage mode="create" onSave={() => navigateTo('adminEvents')} />;
      case 'adminEditEvent':
          return <EventFormPage mode="edit" id={selectedItemId} onSave={() => navigateTo('adminEvents')} />;
      case 'adminNewModule':
          return <ModuleFormPage mode="create" onSave={() => navigateTo('adminModules')} />;
      case 'adminEditModule':
          return <ModuleFormPage mode="edit" id={selectedItemId} onSave={() => navigateTo('adminModules')} />;
      case 'adminNewTheme':
          return <ThemeFormPage mode="create" onSave={() => navigateTo('adminThemes')} />;
      case 'adminEditTheme':
          return <ThemeFormPage mode="edit" id={selectedItemId} onSave={() => navigateTo('adminThemes')} />;
      case 'adminNewFeatured':
          return <FeaturedFormPage mode="create" onSave={() => navigateTo('adminFeatured')} />;
      case 'adminEditFeatured':
          return <FeaturedFormPage mode="edit" id={selectedItemId} onSave={() => navigateTo('adminFeatured')} />;

      // Moodle Admin Views
      case 'adminMoodleInstances':
          return <AdminMoodleInstancesPage navigateTo={navigateTo as any} />;
      case 'adminNewMoodleInstance':
          return <MoodleInstanceFormPage mode="create" onSave={() => navigateTo('adminMoodleInstances')} />;
      case 'adminEditMoodleInstance':
          return <MoodleInstanceFormPage mode="edit" id={selectedItemId} onSave={() => navigateTo('adminMoodleInstances')} />;
      case 'adminMoodleCourses':
          return <AdminMoodleCoursesPage navigateTo={navigateTo as any} />;
      case 'adminNewMoodleCourse':
          return <MoodleCourseFormPage mode="create" onSave={() => navigateTo('adminMoodleCourses')} />;
      case 'adminEditMoodleCourse':
          return <MoodleCourseFormPage mode="edit" id={selectedItemId} onSave={() => navigateTo('adminMoodleCourses')} />;
      case 'adminMoodlePackages':
          return <AdminMoodlePackagesPage navigateTo={navigateTo as any} />;
       case 'adminMoodlePackageUpload':
          return <MoodlePackageUploadPage navigateTo={navigateTo as any} />;
      case 'adminNewMoodlePackage':
          return <MoodlePackageFormPage mode="create" onSave={() => navigateTo('adminMoodlePackages')} />;
      case 'adminEditMoodlePackage':
          return <MoodlePackageFormPage mode="edit" id={selectedItemId} onSave={() => navigateTo('adminMoodlePackages')} />;
      case 'adminMoodleMaps':
          return <AdminMoodleMapsPage navigateTo={navigateTo as any} />;
      case 'adminNewMoodleMap':
          return <MoodleMapFormPage mode="create" onSave={() => navigateTo('adminMoodleMaps')} />;
      case 'adminEditMoodleMap':
          return <MoodleMapFormPage mode="edit" id={selectedItemId} onSave={() => navigateTo('adminMoodleMaps')} />;

      // Offline Player Views
      case 'offlineScorm':
          return <ScormPlayerPage baseUrl={selectedItemId!} onBack={navigateBack} />;
      case 'offlineH5p':
          return <H5pPlayerPage baseUrl={selectedItemId!} onBack={navigateBack} />;


      default:
        return <HomePage onViewEvent={viewEvent} navigateToModule={navigateToModule}/>;
    }
  };

  const isPublicView = !view.startsWith('admin') && !view.startsWith('offline') && view !== 'timeline';
  const isImmersiveTimeline = view === 'timeline';
  const isOfflinePlayer = view.startsWith('offline');

  return (
    <>
      {isPublicView ? (
         <Layout currentView={view as any} navigateTo={navigateTo as any}>
            {renderView()}
         </Layout>
      ) : isImmersiveTimeline ? (
         <div className="bg-[#FAF8F5] min-h-screen">
             {renderView()}
         </div>
      ) : isOfflinePlayer ? (
        <div className="bg-light min-h-screen">{renderView()}</div>
      ) : (
        renderView()
      )}
    </>
  );
}

export default function App() {
    return (
        <AuthProvider>
            <AppContent />
        </AuthProvider>
    )
}

import React, { useState, useEffect, useMemo, useRef } from 'react';
import type { Event } from '../types';
import { getEvents } from '../services/api';
import { formatDate } from '../utils/helpers';
import { THEME_COLORS } from '../constants';
import { Badge } from '../components/ui/Badge';
// Added missing Button import
import { Button } from '../components/ui/Button';
import { ArrowLeftIcon } from '../components/icons/ArrowLeftIcon';
import { ChevronLeftIcon } from '../components/icons/ChevronLeftIcon';
import { ChevronRightIcon } from '../components/icons/ChevronRightIcon';

interface TimelinePageProps {
  onViewEvent: (event: Event) => void;
  timelineSlug?: string | null;
  onBack?: () => void;
}

const getYearFromEvent = (event: Event): number => {
    if (event.year) return event.year;
    if (event.dateISO) return new Date(event.dateISO).getFullYear();
    if (event.period) {
        const match = event.period.match(/\d{4}/);
        if (match) return parseInt(match[0], 10);
    }
    return 9999;
};

const TimelineCard: React.FC<{ 
    event: Event; 
    isActive: boolean; 
    isPrev: boolean; 
    isNext: boolean;
    onClick: () => void;
}> = ({ event, isActive, isPrev, isNext, onClick }) => {

    const cardClass = useMemo(() => {
        if (isActive) return "scale-100 opacity-100 z-30 shadow-2xl translate-x-0";
        if (isPrev) return "scale-90 opacity-40 blur-[2px] -translate-x-full z-10 hidden md:flex";
        if (isNext) return "scale-90 opacity-40 blur-[2px] translate-x-full z-10 hidden md:flex";
        return "scale-75 opacity-0 pointer-events-none hidden";
    }, [isActive, isPrev, isNext]);

    return (
        <div 
            onClick={onClick}
            className={`absolute inset-0 m-auto w-full max-w-[320px] sm:max-w-md h-[450px] sm:h-[500px] transition-all duration-500 ease-out cursor-pointer flex flex-col rounded-3xl overflow-hidden border border-white/30 backdrop-blur-2xl bg-white/40 ${cardClass}`}
        >
            <div className="h-2/5 w-full relative">
                <img 
                    src={event.media[0]?.url || 'https://picsum.photos/400/400'} 
                    alt={event.title}
                    className="w-full h-full object-cover"
                />
                <div className="absolute top-4 left-4">
                    <span className="px-3 py-1 bg-white/20 backdrop-blur-md rounded-full text-xs font-bold text-white border border-white/20">
                        {event.dateISO ? formatDate(new Date(event.dateISO)) : (event.period || event.year)}
                    </span>
                </div>
            </div>
            <div className="flex-1 p-6 flex flex-col justify-between">
                <div>
                    <h3 className="text-xl sm:text-2xl font-bold text-secondary leading-tight mb-3">
                        {event.title}
                    </h3>
                    <p className="text-sm sm:text-base text-dark/70 line-clamp-4 leading-relaxed">
                        {event.summary}
                    </p>
                </div>
                <div className="flex flex-wrap gap-2 mt-4">
                    {event.themes.map(t => (
                        <Badge key={t.id} style={{ backgroundColor: THEME_COLORS[t.slug], color: '#fff', border: 'none' }}>
                            {t.name}
                        </Badge>
                    ))}
                </div>
            </div>
        </div>
    );
};

export const TimelinePage: React.FC<TimelinePageProps> = ({ onViewEvent, timelineSlug, onBack }) => {
    const [events, setEvents] = useState<Event[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [activeIndex, setActiveIndex] = useState(0);
    const containerRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const fetchEvents = async () => {
            setIsLoading(true);
            const allEvents = await getEvents();
            let filtered = allEvents;
            if (timelineSlug) {
                filtered = allEvents.filter(e => e.timelineSlug === timelineSlug);
            }
            const sorted = filtered.sort((a, b) => getYearFromEvent(a) - getYearFromEvent(b));
            setEvents(sorted);
            setIsLoading(false);
        };
        fetchEvents();
    }, [timelineSlug]);

    const goNext = () => setActiveIndex(prev => Math.min(prev + 1, events.length - 1));
    const goPrev = () => setActiveIndex(prev => Math.max(prev - 1, 0));

    // Support Swipe
    const touchStart = useRef<number | null>(null);
    const handleTouchStart = (e: React.TouchEvent) => touchStart.current = e.touches[0].clientX;
    const handleTouchEnd = (e: React.TouchEvent) => {
        if (!touchStart.current) return;
        const diff = touchStart.current - e.changedTouches[0].clientX;
        if (diff > 50) goNext();
        if (diff < -50) goPrev();
        touchStart.current = null;
    };

    if (isLoading) {
        return (
            <div className="h-[60vh] flex items-center justify-center">
                <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary"></div>
            </div>
        );
    }

    if (events.length === 0) {
        return (
            <div className="p-8 text-center">
                <p className="text-muted-foreground">Aucune timeline trouvée pour cette narration.</p>
                {onBack && <Button onClick={onBack} className="mt-4">Retour</Button>}
            </div>
        );
    }

    return (
        <div className="fixed inset-0 z-50 bg-[#FAF8F5] md:relative md:inset-auto md:bg-transparent overflow-hidden flex flex-col h-screen md:h-auto">
            {/* Header / Nav */}
            <div className="p-4 md:p-0 flex items-center justify-between mb-4">
                <button 
                    onClick={onBack} 
                    className="p-2 bg-white/80 backdrop-blur-md rounded-full shadow-sm hover:bg-white transition-colors"
                >
                    <ArrowLeftIcon className="h-5 w-5" />
                </button>
                <div className="text-center flex-1 mx-4">
                    <h1 className="text-lg font-bold text-secondary line-clamp-1">
                        {timelineSlug ? "Frise Narrative" : "L'Histoire en marche"}
                    </h1>
                    <p className="text-xs text-muted-foreground">
                        {activeIndex + 1} sur {events.length} moments clés
                    </p>
                </div>
                <div className="w-10"></div>
            </div>

            {/* Immersion Background Effect */}
            <div className="absolute inset-0 pointer-events-none opacity-20 overflow-hidden">
                <div 
                    className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[800px] h-[800px] rounded-full blur-[120px]"
                    style={{ backgroundColor: THEME_COLORS[events[activeIndex].themes[0]?.slug] || '#E67E22' }}
                ></div>
            </div>

            {/* Carousel Area */}
            <div 
                className="flex-1 relative flex items-center justify-center py-8"
                onTouchStart={handleTouchStart}
                onTouchEnd={handleTouchEnd}
            >
                {/* Navigation Buttons (Desktop) */}
                <button 
                    onClick={goPrev} 
                    disabled={activeIndex === 0}
                    className="absolute left-4 z-40 p-3 rounded-full bg-white/60 backdrop-blur-lg border border-white/40 shadow-lg disabled:opacity-20 hidden md:block"
                >
                    <ChevronLeftIcon className="h-6 w-6 text-secondary" />
                </button>
                <button 
                    onClick={goNext} 
                    disabled={activeIndex === events.length - 1}
                    className="absolute right-4 z-40 p-3 rounded-full bg-white/60 backdrop-blur-lg border border-white/40 shadow-lg disabled:opacity-20 hidden md:block"
                >
                    <ChevronRightIcon className="h-6 w-6 text-secondary" />
                </button>

                {/* Cards Container */}
                <div className="relative w-full h-full max-w-5xl mx-auto flex items-center justify-center px-4">
                    {events.map((event, idx) => (
                        <TimelineCard 
                            key={event.id}
                            event={event}
                            isActive={idx === activeIndex}
                            isPrev={idx === activeIndex - 1}
                            isNext={idx === activeIndex + 1}
                            onClick={() => {
                                if (idx === activeIndex - 1) goPrev();
                                if (idx === activeIndex + 1) goNext();
                                if (idx === activeIndex) onViewEvent(event);
                            }}
                        />
                    ))}
                </div>
            </div>

            {/* Progress Visualizer (Footer) */}
            <div className="p-8 space-y-4">
                <div className="relative h-1 w-full bg-border/30 rounded-full max-w-2xl mx-auto">
                    <div 
                        className="absolute top-0 left-0 h-full bg-primary transition-all duration-500 rounded-full"
                        style={{ width: `${((activeIndex + 1) / events.length) * 100}%` }}
                    ></div>
                    {/* Tick marks */}
                    <div className="absolute inset-0 flex justify-between px-0.5 pointer-events-none">
                        {events.map((_, i) => (
                            <div key={i} className={`h-1 w-1 rounded-full ${i <= activeIndex ? 'bg-primary' : 'bg-border/50'}`}></div>
                        ))}
                    </div>
                </div>
