import React, { useState, useEffect, useMemo, useRef } from 'react';
import type { Event } from '../types';
import { getEvents } from '../services/api';
import { formatDate } from '../utils/helpers';
import { THEME_COLORS } from '../constants';
import { Badge } from '../components/ui/Badge';
import { Button } from '../components/ui/Button';
import { ArrowLeftIcon } from '../components/icons/ArrowLeftIcon';
import { ChevronLeftIcon } from '../components/icons/ChevronLeftIcon';
import { ChevronRightIcon } from '../components/icons/ChevronRightIcon';

interface TimelinePageProps {
  onViewEvent: (event: Event) => void;
  timelineSlug?: string | null;
  initialEventId?: string | null;
  onBack: () => void;
}

const getYearFromEvent = (event: Event): number => {
    if (event.year) return event.year;
    if (event.dateISO) return new Date(event.dateISO).getFullYear();
    if (event.period) {
        const match = event.period.match(/\d{4}/);
        if (match) return parseInt(match[0], 10);
    }
    return 9999;
};

export const TimelinePage: React.FC<TimelinePageProps> = ({ onViewEvent, timelineSlug, initialEventId, onBack }) => {
    const [events, setEvents] = useState<Event[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [activeIndex, setActiveIndex] = useState(0);
    const containerRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const fetchEvents = async () => {
            setIsLoading(true);
            const allEvents = await getEvents();
            let filtered = allEvents;
            if (timelineSlug) {
                filtered = allEvents.filter(e => e.timelineSlug === timelineSlug);
            }
            const sorted = filtered.sort((a, b) => getYearFromEvent(a) - getYearFromEvent(b));
            setEvents(sorted);

            // Set initial index if coming from specific event
            if (initialEventId) {
                const idx = sorted.findIndex(e => e.id === initialEventId);
                if (idx !== -1) setActiveIndex(idx);
            }
            setIsLoading(false);
        };
        fetchEvents();
    }, [timelineSlug, initialEventId]);

    const goNext = () => setActiveIndex(prev => Math.min(prev + 1, events.length - 1));
    const goPrev = () => setActiveIndex(prev => Math.max(prev - 1, 0));

    // Support Swipe
    const touchStart = useRef<number | null>(null);
    const handleTouchStart = (e: React.TouchEvent) => touchStart.current = e.touches[0].clientX;
    const handleTouchEnd = (e: React.TouchEvent) => {
        if (!touchStart.current) return;
        const diff = touchStart.current - e.changedTouches[0].clientX;
        if (diff > 50) goNext();
        if (diff < -50) goPrev();
        touchStart.current = null;
    };

    if (isLoading) {
        return <div className="h-[60vh] flex items-center justify-center animate-pulse"><div className="w-12 h-12 border-4 border-primary border-t-transparent rounded-full animate-spin"></div></div>;
    }

    if (events.length === 0) return <div className="p-8 text-center"><p>Aucun événement trouvé pour cette narration.</p><Button onClick={onBack} className="mt-4">Retour</Button></div>;

    const currentTheme = events[activeIndex].themes[0]?.slug;
    const bgColor = THEME_COLORS[currentTheme] || '#FAF8F5';

    return (
        <div className="fixed inset-0 z-50 bg-[#FAF8F5] overflow-hidden flex flex-col h-screen select-none">
            {/* Immersive Background Gradient */}
            <div 
                className="absolute inset-0 opacity-10 blur-[100px] transition-colors duration-1000"
                style={{ backgroundColor: bgColor }}
            ></div>

            {/* Header */}
            <header className="relative z-10 px-4 pt-6 pb-2 flex items-center justify-between">
                <button onClick={onBack} className="p-3 bg-white/60 backdrop-blur-md rounded-full shadow-sm hover:bg-white transition-colors">
                    <ArrowLeftIcon className="h-6 w-6" />
                </button>
                <div className="text-center">
                    <h2 className="text-lg font-bold text-secondary">
                        {timelineSlug === 'samuel-etoo' ? 'Parcours de Samuel Eto\'o' : 'Narration Temporelle'}
                    </h2>
                    <p className="text-xs text-muted-foreground uppercase tracking-widest font-bold">
                        {activeIndex + 1} / {events.length} Moments
                    </p>
                </div>
                <div className="w-12"></div>
            </header>

            {/* Immersive Viewport */}
            <div 
                className="flex-1 relative flex items-center justify-center overflow-hidden"
                onTouchStart={handleTouchStart}
                onTouchEnd={handleTouchEnd}
            >
                {/* Desktop Navigation */}
                <button onClick={goPrev} disabled={activeIndex === 0} className="absolute left-8 z-40 p-4 rounded-full bg-white/40 backdrop-blur-xl border border-white/30 shadow-lg disabled:opacity-10 hidden md:block">
                    <ChevronLeftIcon className="h-8 w-8" />
                </button>
                <button onClick={goNext} disabled={activeIndex === events.length - 1} className="absolute right-8 z-40 p-4 rounded-full bg-white/40 backdrop-blur-xl border border-white/30 shadow-lg disabled:opacity-10 hidden md:block">
                    <ChevronRightIcon className="h-8 w-8" />
                </button>

                <div className="relative w-full max-w-4xl h-[550px] flex items-center justify-center">
                    {events.map((event, idx) => {
                        const offset = idx - activeIndex;
                        const isFocused = offset === 0;
                        const isPrev = offset === -1;
                        const isNext = offset === 1;
                        const isFar = Math.abs(offset) > 1;

                        return (
                            <div
                                key={event.id}
                                onClick={() => isFocused ? onViewEvent(event) : (isPrev ? goPrev() : isNext ? goNext() : null)}
                                className={`absolute transition-all duration-700 ease-[cubic-bezier(0.22,1,0.36,1)] w-[320px] sm:w-[450px] rounded-[2.5rem] overflow-hidden border border-white/40 backdrop-blur-2xl bg-white/45 shadow-2xl cursor-pointer
                                    ${isFocused ? 'z-30 scale-100 opacity-100' : ''}
                                    ${isPrev ? 'z-20 -translate-x-[70%] scale-90 opacity-40 blur-[2px]' : ''}
                                    ${isNext ? 'z-20 translate-x-[70%] scale-90 opacity-40 blur-[2px]' : ''}
                                    ${isFar ? 'opacity-0 scale-75' : ''}
                                `}
                            >
                                <div className="h-60 relative">
                                    <img src={event.media[0]?.url} alt="" className="w-full h-full object-cover" />
                                    <div className="absolute top-6 left-6 px-4 py-1.5 bg-black/40 backdrop-blur-md rounded-full text-white text-xs font-bold tracking-wider">
                                        {event.dateISO ? formatDate(new Date(event.dateISO)) : (event.period || event.year)}
                                    </div>
                                </div>
                                <div className="p-8 space-y-4">
                                    <h3 className="text-2xl font-bold text-secondary leading-tight">{event.title}</h3>
                                    <p className="text-dark/70 text-sm leading-relaxed line-clamp-4">{event.summary}</p>
                                    <div className="flex flex-wrap gap-2 pt-2">
                                        {event.themes.map(t => (
                                            <Badge key={t.id} style={{ backgroundColor: THEME_COLORS[t.slug] || '#ccc', borderColor: 'transparent', color: '#fff' }}>{t.name}</Badge>
                                        ))}
                                    </div>
                                </div>
                            </div>
                        );
                    })}
                </div>
            </div>

            {/* Bottom Magnetic Progress Bar */}
            <div className="p-8 space-y-4 relative z-10">
                <div className="max-w-2xl mx-auto relative h-1.5 w-full bg-black/5 rounded-full">
                    <div 
                        className="absolute h-full bg-primary transition-all duration-700 rounded-full"
                        style={{ width: `${((activeIndex + 1) / events.length) * 100}%` }}
                    ></div>
                    {/* Magnetic Dots */}
                    <div className="absolute inset-0 flex justify-between px-0.5 items-center pointer-events-none">
                        {events.map((_, i) => (
                            <div key={i} className={`h-2.5 w-2.5 rounded-full border-2 border-white shadow-sm transition-all duration-500 ${i <= activeIndex ? 'bg-primary scale-125' : 'bg-black/10'}`}></div>
                        ))}
                    </div>
                </div>
                <div className="flex justify-between max-w-2xl mx-auto text-[10px] font-bold text-muted-foreground uppercase tracking-widest px-2">
                    <span>DÉBUT</span>
                    <span>EN SAVOIR PLUS • CLIQUER SUR LA CARTE</span>
                    <span>FIN</span>
                </div>
            </div>
        </div>
    );
};

