import React, { useState, useEffect, useMemo, useRef } from 'react';
import type { Event } from '../types';
import { getEvents } from '../services/api';
import { formatDate } from '../utils/helpers';
import { THEME_COLORS, TIMELINES } from '../constants';
import { Badge } from '../components/ui/Badge';
import { Button } from '../components/ui/Button';
import { ArrowLeftIcon } from '../components/icons/ArrowLeftIcon';
import { ChevronLeftIcon } from '../components/icons/ChevronLeftIcon';
import { ChevronRightIcon } from '../components/icons/ChevronRightIcon';

interface TimelinePageProps {
  onViewEvent: (event: Event) => void;
  timelineSlug?: string | null;
  initialEventId?: string | null;
  onBack: () => void;
}

const getYearFromEvent = (event: Event): number => {
    if (event.year) return event.year;
    if (event.dateISO) return new Date(event.dateISO).getFullYear();
    if (event.period) {
        const match = event.period.match(/\d{4}/);
        if (match) return parseInt(match[0], 10);
    }
    return 9999;
};

export const TimelinePage: React.FC<TimelinePageProps> = ({ onViewEvent, timelineSlug, initialEventId, onBack }) => {
    const [events, setEvents] = useState<Event[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [activeIndex, setActiveIndex] = useState(0);
    const timelineData = useMemo(() => TIMELINES.find(t => t.slug === timelineSlug), [timelineSlug]);

    useEffect(() => {
        const fetchEvents = async () => {
            if (!timelineSlug) {
                setIsLoading(false);
                return;
            }

            setIsLoading(true);
            const allEvents = await getEvents();

            // FILTRAGE STRICT : Uniquement les événements de ce parcours spécifique
            const filtered = allEvents.filter(e => e.timelineSlug === timelineSlug);

            // Tri chronologique obligatoire pour la cohérence du parcours
            const sorted = filtered.sort((a, b) => {
                const dateA = a.dateISO ? new Date(a.dateISO).getTime() : getYearFromEvent(a);
                const dateB = b.dateISO ? new Date(b.dateISO).getTime() : getYearFromEvent(b);
                return dateA - dateB;
            });

            setEvents(sorted);

            // Positionnement intelligent si on vient d'un moment précis
            if (initialEventId) {
                const idx = sorted.findIndex(e => e.id === initialEventId);
                if (idx !== -1) {
                    setActiveIndex(idx);
                }
            } else {
                setActiveIndex(0);
            }
            setIsLoading(false);
        };
        fetchEvents();
    }, [timelineSlug, initialEventId]);

    const goNext = () => setActiveIndex(prev => Math.min(prev + 1, events.length - 1));
    const goPrev = () => setActiveIndex(prev => Math.max(prev - 1, 0));

    // Swipe handlers
    const touchStart = useRef<number | null>(null);
    const handleTouchStart = (e: React.TouchEvent) => touchStart.current = e.touches[0].clientX;
    const handleTouchEnd = (e: React.TouchEvent) => {
        if (!touchStart.current) return;
        const diff = touchStart.current - e.changedTouches[0].clientX;
        if (diff > 50) goNext();
        if (diff < -50) goPrev();
        touchStart.current = null;
    };

    if (isLoading) {
        return (
            <div className="h-screen flex flex-col items-center justify-center bg-light font-sans">
                <div className="w-16 h-16 border-4 border-primary border-t-transparent rounded-full animate-spin mb-4 shadow-xl"></div>
                <p className="text-muted-foreground font-black uppercase tracking-widest text-xs animate-pulse">Narration en cours...</p>
            </div>
        );
    }

    // Sécurité : Si aucun slug n'est fourni, on force le retour à la sélection
    if (!timelineSlug || events.length === 0) return (
        <div className="h-screen flex flex-col items-center justify-center p-8 text-center space-y-6 bg-light font-sans">
            <div className="p-6 bg-white rounded-3xl shadow-soft border border-border">
                <p className="text-xl font-black text-secondary uppercase tracking-tight mb-2">Choisir une histoire</p>
                <p className="text-muted-foreground mb-6">Veuillez sélectionner un récit depuis la page d'exploration.</p>
                <Button onClick={onBack} className="rounded-full px-8 py-6 h-auto font-black uppercase tracking-[0.2em] text-[10px]">
                    Voir les récits disponibles
                </Button>
            </div>
        </div>
    );

    const activeEvent = events[activeIndex];
    const accentColor = THEME_COLORS[activeEvent.themes[0]?.slug] || '#E67E22';

    return (
        <div className="fixed inset-0 z-50 bg-[#FAF8F5] overflow-hidden flex flex-col h-screen select-none font-sans">
            {/* Ambient Background Gradient */}
            <div 
                className="absolute inset-0 opacity-20 blur-[120px] transition-colors duration-1000 ease-in-out"
                style={{ backgroundColor: accentColor }}
            ></div>

            {/* Header / Nav */}
            <header className="relative z-10 px-6 pt-8 pb-4 flex items-center justify-between">
                <button 
                    onClick={onBack} 
                    className="p-3 bg-white/40 backdrop-blur-xl border border-white/20 rounded-full shadow-sm hover:bg-white/60 transition-all active:scale-90"
                    aria-label="Retour"
                >
                    <ArrowLeftIcon className="h-6 w-6 text-secondary" />
                </button>
                <div className="text-center">
                    <h2 className="text-xl font-black text-secondary drop-shadow-sm uppercase tracking-tight">
                        {timelineData?.title}
                    </h2>
                    <div className="flex items-center justify-center gap-2 mt-1">
                        <span className="w-1.5 h-1.5 rounded-full bg-primary animate-pulse" />
                        <p className="text-[10px] text-muted-foreground uppercase tracking-[0.2em] font-black">
                            Moment {activeIndex + 1} / {events.length}
                        </p>
                    </div>
                </div>
                <div className="w-12"></div>
            </header>

            {/* Immersive Viewport */}
            <div 
                className="flex-1 relative flex items-center justify-center"
                onTouchStart={handleTouchStart}
                onTouchEnd={handleTouchEnd}
            >
                {/* Navigation Arrows (Desktop) */}
                <button 
                    onClick={goPrev} 
                    disabled={activeIndex === 0} 
                    className="absolute left-10 z-40 p-5 rounded-full bg-white/30 backdrop-blur-2xl border border-white/30 shadow-xl disabled:opacity-0 transition-all hover:bg-white/50 hidden md:block"
                >
                    <ChevronLeftIcon className="h-8 w-8 text-secondary" />
                </button>
                <button 
                    onClick={goNext} 
                    disabled={activeIndex === events.length - 1} 
                    className="absolute right-10 z-40 p-5 rounded-full bg-white/30 backdrop-blur-2xl border border-white/30 shadow-xl disabled:opacity-0 transition-all hover:bg-white/50 hidden md:block"
                >
                    <ChevronRightIcon className="h-8 w-8 text-secondary" />
                </button>

                {/* Perspective Container */}
                <div className="relative w-full max-w-5xl h-[580px] flex items-center justify-center overflow-visible">
                    {events.map((event, idx) => {
                        const offset = idx - activeIndex;
                        const isFocused = offset === 0;
                        const isPrev = offset === -1;
                        const isNext = offset === 1;
                        const isFar = Math.abs(offset) > 1;

                        return (
                            <div
                                key={event.id}
                                onClick={() => {
                                    if (isPrev) goPrev();
                                    else if (isNext) goNext();
                                    else if (isFocused) onViewEvent(event);
                                }}
                                className={`absolute transition-all duration-700 cubic-bezier(0.23, 1, 0.32, 1) w-[310px] sm:w-[460px] rounded-[3rem] overflow-hidden border border-white/40 backdrop-blur-3xl shadow-2xl cursor-pointer
                                    ${isFocused ? 'z-30 scale-100 opacity-100 translate-x-0 rotate-0' : ''}
                                    ${isPrev ? 'z-20 -translate-x-[65%] sm:-translate-x-[85%] scale-90 opacity-40 blur-[3px] -rotate-3' : ''}
                                    ${isNext ? 'z-20 translate-x-[65%] sm:translate-x-[85%] scale-90 opacity-40 blur-[3px] rotate-3' : ''}
                                    ${isFar ? 'opacity-0 scale-75 pointer-events-none' : ''}
                                    bg-white/35
                                `}
                            >
                                {/* Card Media */}
                                <div className="h-64 relative overflow-hidden">
                                    <img 
                                        src={event.media[0]?.url || 'https://picsum.photos/800/600'} 
                                        alt="" 
                                        className={`w-full h-full object-cover transition-transform duration-[2000ms] ${isFocused ? 'scale-110' : 'scale-100'}`} 
                                    />
                                    <div className="absolute top-6 left-6 px-4 py-2 bg-black/40 backdrop-blur-md rounded-2xl text-white text-[11px] font-bold tracking-widest border border-white/10 uppercase">
                                        {event.dateISO ? formatDate(new Date(event.dateISO), { year: 'numeric', month: 'long', day: 'numeric', timeZone: 'UTC' }) : (event.period || event.year)}
                                    </div>
                                </div>

                                {/* Card Content */}
                                <div className="p-8 sm:p-10 flex flex-col h-full">
                                    <h3 className="text-2xl sm:text-3xl font-black text-secondary leading-tight mb-4 tracking-tight">
                                        {event.title}
                                    </h3>
                                    <p className="text-dark/80 text-sm sm:text-base leading-relaxed line-clamp-4 font-medium mb-6">
                                        {event.summary}
                                    </p>

                                    <div className="mt-auto flex flex-wrap gap-2">
                                        {event.themes.map(t => (
                                            <Badge 
                                                key={t.id} 
                                                style={{ backgroundColor: THEME_COLORS[t.slug] || '#ccc', border: 'none', color: '#fff' }}
                                                className="px-3 py-1 rounded-full text-[10px] font-bold uppercase tracking-wider"
                                            >
                                                {t.name}
                                            </Badge>
                                        ))}
                                    </div>
                                </div>
                            </div>
                        );
                    })}
                </div>
            </div>

            {/* Magnetic Timeline Bar (Footer) */}
            <div className="p-8 sm:p-12 relative z-10 bg-gradient-to-t from-[#FAF8F5] via-[#FAF8F5]/80 to-transparent">
                <div className="max-w-3xl mx-auto space-y-6">
                    <div className="relative h-1 w-full bg-black/5 rounded-full overflow-visible">
                        {/* Fill */}
                        <div 
                            className="absolute h-full bg-primary transition-all duration-700 ease-out rounded-full shadow-[0_0_15px_rgba(230,126,34,0.4)]"
                            style={{ width: `${((activeIndex + 1) / events.length) * 100}%` }}
                        ></div>

                        {/* Interactive Magnetic Dots */}
                        <div className="absolute inset-0 flex justify-between px-0 items-center pointer-events-none">
                            {events.map((e, i) => (
                                <div 
                                    key={e.id} 
                                    className={`relative flex items-center justify-center transition-all duration-500
                                        ${i === activeIndex ? 'scale-125' : 'scale-100'}
                                    `}
                                >
                                    <div className={`h-3 w-3 rounded-full border-2 border-white shadow-md transition-all duration-300 
                                        ${i <= activeIndex ? 'bg-primary' : 'bg-black/10'}
                                    `}></div>

                                    {/* Tick Label (Years) */}
                                    { (i === 0 || i === events.length - 1 || i === activeIndex) && (
                                        <span className="absolute -top-6 text-[9px] font-black text-secondary/60 whitespace-nowrap uppercase tracking-tighter">
                                            {e.year || '...'}
                                        </span>
                                    )}
                                </div>
                            ))}
                        </div>
                    </div>

                    <div className="flex justify-between items-center text-[9px] font-black text-muted-foreground uppercase tracking-[0.25em] px-1 opacity-60">
                        <span>Origines</span>
                        <div className="flex items-center gap-2">
                            <span className="animate-pulse">●</span>
                            <span>Glisser pour voyager</span>
                        </div>
                        <span>Présent</span>
                    </div>
                </div>
            </div>
        </div>
    );
};

