type AdminView = 'adminDashboard' | 'adminTimelines' | 'adminNewTimeline' | 'adminEditTimeline';

interface AdminTimelinesPageProps {
  navigateTo: (view: AdminView, id?: string) => void;
}

export const AdminTimelinesPage: React.FC<AdminTimelinesPageProps> = ({ navigateTo }) => {
    const [data, setData] = useState<{ items: TimelineNarrative[] }>({ items: [] });
    const [isLoading, setIsLoading] = useState(true);

    const loadTimelines = async () => {
        setIsLoading(true);
        const result = await adminApi.listTimelines();
        setData(result);
        setIsLoading(false);
    }

    useEffect(() => {
        loadTimelines();
    }, []);

    const handleDelete = async (id: string) => {
      if (window.confirm('Voulez-vous vraiment supprimer cette timeline ? Tous les moments associés seront perdus.')) {
        await adminApi.deleteTimeline(id);
        loadTimelines();
