                ) : (
                    <div className="grid gap-4">
                        {data.items.length === 0 ? (
                            <div className="p-12 text-center border rounded-3xl bg-card border-dashed">
                                <p className="text-muted-foreground">Aucune timeline créée pour le moment.</p>
                            </div>
                        ) : data.items.map((tl) => (
                            <div key={tl.id} className="group rounded-[2rem] border bg-card p-5 flex items-center justify-between hover:shadow-soft transition-all">
                                <div className="flex items-center gap-5">
                                    <img src={tl.thumbnail} alt="" className="w-20 h-16 rounded-2xl object-cover bg-muted" />
                                    <div className="space-y-1">
                                        <div className="flex items-center gap-3">
