"use client";
import React, { useState } from 'react';
import { useForm, useFieldArray } from 'react-hook-form';
import { timelineFormSchema, TimelineFormData } from '../../schemas/admin';
import { adminApi } from '../../services/adminApi';
import { Button } from '../ui/Button';
import { Input } from '../ui/Input';
import { Label } from '../ui/Label';
import { Textarea } from '../ui/Textarea';
import { Card, CardContent } from '../ui/Card';
import { Separator } from '../ui/Separator';
import { XIcon } from '../icons/XIcon';
import { TimelineIcon } from '../icons/TimelineIcon';

interface Props {
  mode: "create"|"edit";
  initialData?: any;
  onSave: () => void;
}

const zodResolver = (schema: any) => async (data: any) => {
  try {
    const parsed = await schema.parseAsync(data);
    return { values: parsed, errors: {} };
  } catch (error: any) {
    return { values: {}, errors: error.formErrors.fieldErrors };
  }
};

export function TimelineForm({ mode, initialData, onSave }: Props){
  const form = useForm<TimelineFormData>({
    resolver: zodResolver(timelineFormSchema),
    defaultValues: initialData ? {
        ...initialData,
        status: initialData.status || 'draft',
        moments: initialData.moments || []
    } : { 
        title: "", slug: "", type: 'personnage', status: 'draft',
        shortDescription: "", thumbnail: "", periodLabel: "",
        moments: []
    }
  });

  const { fields: moments, append, remove, move } = useFieldArray({
    control: form.control,
    name: "moments"
  });

  async function onSubmit(values: TimelineFormData){
    try {
        if (mode === 'create') {
            await adminApi.createTimeline(values);
        } else {
            await adminApi.updateTimeline(initialData.id, values);
        }
        onSave();
    } catch (e) {
        alert('Erreur lors de l’enregistrement');
    }
  }

  return (
    <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-12 pb-24">
      {/* SECTION 1: INFOS GÉNÉRALES */}
      <section className="space-y-6">
        <div className="flex items-center gap-3">
            <div className="p-2 bg-primary/10 rounded-xl">
                <TimelineIcon className="h-5 w-5 text-primary" />
            </div>
            <h2 className="text-xl font-bold text-secondary">1. Informations générales</h2>
        </div>
        <Card className="rounded-[2.5rem] border-muted shadow-sm overflow-hidden">
            <CardContent className="p-8 space-y-6">
                <div className="grid md:grid-cols-2 gap-6">
                    <div className="space-y-2">
                        <Label>Titre du parcours</Label>
                        <Input {...form.register('title')} placeholder="Ex: Nelson Mandela : Un long chemin..." />
                        {form.formState.errors.title && <p className="text-xs text-destructive">{form.formState.errors.title.message}</p>}
                    </div>
                    <div className="space-y-2">
                        <Label>Slug (URL)</Label>
                        <Input {...form.register('slug')} placeholder="nelson-mandela" />
                    </div>
                </div>

                <div className="grid md:grid-cols-3 gap-6">
                    <div className="space-y-2">
                        <Label>Type</Label>
                        <select className="input" {...form.register('type')}>
                            <option value="personnage">👤 Personnage</option>
                            <option value="evenement">🎭 Événement majeur</option>
                        </select>
                    </div>
                    <div className="space-y-2">
                        <Label>Statut</Label>
                        <select className="input" {...form.register('status')}>
                            <option value="draft">📁 Brouillon</option>
                            <option value="published">✅ Publiée</option>
                        </select>
                    </div>
                    <div className="space-y-2">
                        <Label>Période (libellé)</Label>
                        <Input {...form.register('periodLabel')} placeholder="Ex: 1918 - 2013" />
                    </div>
                </div>

                <div className="space-y-2">
                    <Label>Image de couverture (URL)</Label>
                    <Input {...form.register('thumbnail')} placeholder="https://images..." />
                </div>

                <div className="space-y-2">
                    <Label>Description courte (liste)</Label>
                    <Textarea {...form.register('shortDescription')} rows={2} placeholder="S'affiche sur la page de sélection..." />
                </div>

                <div className="space-y-2">
                    <Label>Description longue (optionnelle)</Label>
                    <Textarea {...form.register('longDescription')} rows={4} placeholder="Introduction détaillée du parcours..." />
                </div>
            </CardContent>
        </Card>
      </section>

      {/* SECTION 2: LES MOMENTS */}
      <section className="space-y-6">
         <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
                <div className="p-2 bg-primary/10 rounded-xl">
                    <div className="h-5 w-5 border-2 border-primary rounded-full flex items-center justify-center text-[10px] font-bold text-primary">2</div>
                </div>
                <h2 className="text-xl font-bold text-secondary">2. Moments clés du parcours</h2>
            </div>
            <Button 
                type="button" 
                variant="outline" 
                className="rounded-full px-6 border-primary text-primary hover:bg-primary/5"
                onClick={() => append({ title: "", narrative: "", timeType: 'date', position: moments.length, media: [] })}
            >
                + Ajouter un moment
            </Button>
         </div>

         <div className="space-y-4">
            {moments.map((moment, idx) => (
                <Card key={moment.id} className="rounded-[2rem] border-muted shadow-sm overflow-hidden group">
                    <div className="bg-muted/30 px-6 py-3 flex items-center justify-between border-b">
                        <div className="flex items-center gap-3">
                            <span className="bg-secondary text-white w-6 h-6 rounded-full flex items-center justify-center text-xs font-black">
                                {idx + 1}
                            </span>
                            <span className="font-bold text-sm text-secondary uppercase tracking-wider">Moment narratif</span>
                        </div>
                        <div className="flex items-center gap-2">
                            <Button type="button" variant="ghost" size="sm" onClick={() => move(idx, idx - 1)} disabled={idx === 0}>↑</Button>
                            <Button type="button" variant="ghost" size="sm" onClick={() => move(idx, idx + 1)} disabled={idx === moments.length - 1}>↓</Button>
                            <Button type="button" variant="ghost" size="sm" className="text-destructive hover:bg-destructive/10" onClick={() => remove(idx)}>
                                <XIcon className="h-4 w-4" />
                            </Button>
                        </div>
                    </div>
                    <CardContent className="p-8 space-y-6">
                        <div className="grid md:grid-cols-2 gap-6">
                            <div className="space-y-2">
                                <Label>Titre du moment</Label>
                                <Input {...form.register(`moments.${idx}.title` as const)} placeholder="Ex: Arrestation de Rivonia" />
                            </div>
                            <div className="grid grid-cols-2 gap-4">
                                <div className="space-y-2">
                                    <Label>Temporalité</Label>
                                    <select className="input" {...form.register(`moments.${idx}.timeType` as const)}>
                                        <option value="date">📅 Date précise</option>
                                        <option value="period">⏳ Période (texte)</option>
                                    </select>
                                </div>
                                <div className="space-y-2">
                                    <Label>Valeur</Label>
                                    <Input 
                                        {...form.register(`moments.${idx}.dateExact` as const)} 
                                        placeholder="YYYY-MM-DD" 
                                        type={form.watch(`moments.${idx}.timeType`) === 'date' ? 'date' : 'text'}
                                    />
                                </div>
                            </div>
                        </div>
                        <div className="space-y-2">
                            <Label>Récit narratif</Label>
                            <Textarea {...form.register(`moments.${idx}.narrative` as const)} rows={4} placeholder="Racontez ce moment..." />
                        </div>
                        <div className="space-y-2">
                            <Label>URL de l'image</Label>
                            <Input defaultValue={moment.media?.[0]?.url} onChange={(e) => {
                                form.setValue(`moments.${idx}.media`, [{ type: 'image', url: e.target.value }]);
                            }} placeholder="Lien vers une belle image..." />
                        </div>
                    </CardContent>
                </Card>
            ))}

            {moments.length === 0 && (
                <div className="p-24 text-center border-2 border-dashed rounded-[3rem] text-muted-foreground bg-muted/10">
                    <p className="font-medium">Commencez par ajouter le premier moment de cette histoire.</p>
                </div>
            )}
         </div>
      </section>

      {/* SECTION 3: CALENDRIER */}
      <section className="space-y-6">
        <div className="flex items-center gap-3">
            <div className="p-2 bg-primary/10 rounded-xl">
                <div className="h-5 w-5 border-2 border-primary rounded-full flex items-center justify-center text-[10px] font-bold text-primary">3</div>
            </div>
            <h2 className="text-xl font-bold text-secondary">3. Liaison avec le calendrier</h2>
        </div>
        <Card className="rounded-[2.5rem] border-muted shadow-sm bg-primary/5">
            <CardContent className="p-8">
                <p className="text-sm text-muted-foreground leading-relaxed mb-6">
                    Note : Pour lier ce parcours à des dates du calendrier, éditez directement les <strong>événements du calendrier</strong>. 
                    Vous pourrez y sélectionner ce parcours dans le menu "Lien Timeline".
                </p>
                <div className="flex flex-wrap gap-3">
                    <Button variant="outline" className="rounded-full border-primary/20 hover:bg-white transition-colors">
                        Accéder aux événements calendrier
                    </Button>
                </div>
            </CardContent>
        </Card>
      </section>

      <div className="fixed bottom-10 right-10 left-10 md:left-auto md:w-96 z-50">
          <Card className="rounded-full shadow-2xl border-none bg-secondary text-white p-2">
            <CardContent className="p-0 flex items-center justify-between pl-6">
                <span className="font-bold text-sm uppercase tracking-widest">{mode === 'create' ? 'Nouveau récit' : 'Modifications'}</span>
                <Button type="submit" className="rounded-full px-10 h-14 bg-white text-secondary hover:bg-white/90 font-black uppercase tracking-widest text-xs">
                    {mode === 'create' ? 'Publier l\'histoire' : 'Enregistrer'}
                </Button>
            </CardContent>
          </Card>
      </div>
    </form>
  );
}

