"use client";
import React from 'react';
import { useForm, useFieldArray, Controller } from 'react-hook-form';
import { moduleFormSchema, ModuleFormData } from '../../schemas/admin';
import { adminApi } from '../../services/adminApi';
import { Button } from '../ui/Button';
import { Input } from '../ui/Input';
import { Label } from '../ui/Label';
import { Textarea } from '../ui/Textarea';
import { XIcon } from '../icons/XIcon';

interface ModuleFormProps {
  mode: "create"|"edit";
  initialData?: any;
  onSave: () => void;
}

const zodResolver = (schema: any) => async (data: any) => {
  try {
    const values = await schema.parseAsync(data);
    return { values, errors: {} };
  } catch (error: any) {
    if (error.flatten) {
      const fieldErrors = error.flatten().fieldErrors;
      const formattedErrors = Object.keys(fieldErrors).reduce((acc: any, key) => {
        acc[key] = { message: fieldErrors[key][0] };
        return acc;
      }, {});
      return { values: {}, errors: formattedErrors };
    }
    return { values: {}, errors: { root: { message: error.message } } };
  }
};

export function ModuleForm({ mode, initialData, onSave }: ModuleFormProps){
  const form = useForm<ModuleFormData>({
    resolver: zodResolver(moduleFormSchema),
    defaultValues: initialData ? {
        ...initialData,
        level: initialData.level ?? null,
        language: initialData.language ?? null,
        objectives: initialData.objectives ?? [],
        tags: initialData.tags ?? [],
        eventIds: initialData.eventIds ?? [],
        creatorIds: initialData.creators?.map((c: any) => c.id) ?? [],
        sponsorIds: initialData.sponsors?.map((s: any) => s.id) ?? [],
        sections: initialData.sections ?? [],
        moduleType: initialData.moduleType ?? 'internal',
        moodleCourseUrl: initialData.moodleCourseUrl ?? null,
    } : {
        title: "", slug: "", summary: "", objectives: [""], level: 'Débutant',
        tags: [], eventIds: [], creatorIds: [], sponsorIds: [], sections: [],
        moduleType: 'internal',
        moodleCourseUrl: "",
    }
  });

  const { fields: sections, append, remove } = useFieldArray({
    control: form.control,
    name: "sections"
  });

  const { fields: objectives, append: appendObjective, remove: removeObjective } = useFieldArray({
    control: form.control,
    name: "objectives"
  });

  const moduleType = form.watch('moduleType');


  async function onSubmit(values: ModuleFormData){
    try {
        if (mode === 'create') {
            await adminApi.createModule(values);
        } else {
            await adminApi.updateModule(initialData.id, values);
        }
        onSave();
    } catch (error) {
        console.error("Erreur lors de l’enregistrement", error);
        alert("Erreur lors de l’enregistrement");
    }
  }

  const handleDelete = async () => {
    if (!initialData?.id) return;
    if (confirm('Supprimer ce module ?')) {
        await adminApi.deleteModule(initialData.id);
        onSave();
    }
  };


  return (
    <div className="container py-6 max-w-3xl">
      <h1 className="text-xl font-semibold mb-4">{mode === 'create' ? 'Créer un module' : 'Éditer un module'}</h1>
      <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4">
        {/* Module Type selection */}
        <div>
            <Label>Type de module</Label>
            <div className="flex gap-4 p-2 border rounded-md">
                <label className="flex items-center gap-2 cursor-pointer">
                    <input type="radio" value="internal" {...form.register('moduleType')} />
                    Interne (leçons dans Kasuku)
                </label>
                <label className="flex items-center gap-2 cursor-pointer">
                    <input type="radio" value="moodle" {...form.register('moduleType')} />
                    Externe (lien Moodle)
                </label>
            </div>
        </div>

        {/* Basic Info */}
        <Input placeholder="Title" {...form.register('title')} />
        {form.formState.errors.title && <p className="text-sm text-red-500">{form.formState.errors.title.message}</p>}
        <Input placeholder="Slug" {...form.register('slug')} />
        {form.formState.errors.slug && <p className="text-sm text-red-500">{form.formState.errors.slug.message}</p>}
        <Textarea placeholder="Summary" {...form.register('summary')} />
        {form.formState.errors.summary && <p className="text-sm text-red-500">{form.formState.errors.summary.message}</p>}
        <Input placeholder="Thumbnail URL" {...form.register('thumbnail')} />

        <div className="grid grid-cols-2 gap-4">
            <select className="input" {...form.register('level')}>
                <option value="Débutant">Débutant</option>
                <option value="Intermédiaire">Intermédiaire</option>
                <option value="Avancé">Avancé</option>
            </select>
            <select className="input" {...form.register('language')}>
                <option value="fr">Français</option>
                <option value="en">English</option>
            </select>
        </div>

        {/* Objectives */}
        <div>
            <Label>Objectives</Label>
            {objectives.map((field, index) => (
                <div key={field.id} className="flex gap-2 mb-2">
                    <Input {...form.register(`objectives.${index}` as const)} />
                    <Button type="button" variant="outline" onClick={() => removeObjective(index)}><XIcon className="h-4 w-4"/></Button>
                </div>
            ))}
            <Button type="button" size="sm" onClick={() => appendObjective("")}>Add Objective</Button>
            {form.formState.errors.objectives && <p className="text-sm text-red-500">{form.formState.errors.objectives.message}</p>}
        </div>

        {/* Conditional Fields */}
        {moduleType === 'moodle' ? (
             <div>
                <Label htmlFor="moodleCourseUrl">URL du cours Moodle</Label>
                <Input id="moodleCourseUrl" {...form.register('moodleCourseUrl')} />
                {form.formState.errors.moodleCourseUrl && <p className="text-sm text-red-500">{form.formState.errors.moodleCourseUrl.message}</p>}
            </div>
        ) : (
          <div>
            <h3 className="text-lg font-medium">Sections</h3>
            {sections.map((section, sectionIndex) => (
              <div key={section.id} className="p-4 border rounded-lg mt-2">
                <div className="flex gap-2">
                  <Input placeholder="Section Title" {...form.register(`sections.${sectionIndex}.title` as const)} />
                  <Input type="number" placeholder="Order" {...form.register(`sections.${sectionIndex}.order` as const, { valueAsNumber: true })} />
                  <Button type="button" variant="outline" onClick={() => remove(sectionIndex)}>Remove Section</Button>
                </div>

                <LessonsArray sectionIndex={sectionIndex} control={form.control} register={form.register} />
              </div>
            ))}
            <Button type="button" size="sm" className="mt-2" onClick={() => append({ title: "", order: sections.length, lessons: [] })}>
              Add Section
            </Button>
          </div>
        )}


        <div className="flex items-center gap-3 pt-4">
          <Button type="submit">Enregistrer</Button>
          {mode === 'edit' && (
            <Button variant="destructive" type="button" onClick={handleDelete}>Supprimer</Button>
          )}
        </div>
      </form>
    </div>
  );
}

const LessonsArray = ({ sectionIndex, control, register }: { sectionIndex: number; control: any; register: any; }) => {
  const { fields, append, remove } = useFieldArray({
    control,
    name: `sections[${sectionIndex}].lessons`
  });

  return (
    <div className="pl-4 mt-4 space-y-2">
      <h4 className="font-semibold">Lessons</h4>
      {fields.map((lesson, lessonIndex) => (
        <div key={lesson.id} className="p-2 border rounded-md grid grid-cols-2 gap-2">
          <Input placeholder="Lesson Title" {...register(`sections.${sectionIndex}.lessons.${lessonIndex}.title` as const)} />
          <Input type="number" placeholder="Order" {...register(`sections.${sectionIndex}.lessons.${lessonIndex}.order` as const, { valueAsNumber: true })} />
           <select className="input" {...register(`sections.${sectionIndex}.lessons.${lessonIndex}.type` as const)}>
              <option value="video">Video</option>
              <option value="audio">Audio</option>
              <option value="pdf">PDF</option>
              <option value="quiz">Quiz</option>
           </select>
          <Input type="number" placeholder="Duration (min)" {...register(`sections.${sectionIndex}.lessons.${lessonIndex}.durationMin` as const, { valueAsNumber: true })} />
          <div className="col-span-2">
             <Input placeholder="URL (optional)" {...register(`sections.${sectionIndex}.lessons.${lessonIndex}.url` as const)} />
          </div>
          <Button type="button" variant="outline" size="sm" onClick={() => remove(lessonIndex)}>Remove Lesson</Button>
        </div>
      ))}
      <Button type="button" size="sm" onClick={() => append({ title: "", order: fields.length, type: "video" })}>
        Add Lesson
      </Button>
    </div>
  );
};

