type View = 'home' | 'calendar' | 'favorites' | 'event' | 'timelines' | 'timeline' | 'module' | 'modules' | 
            'adminLogin' | 'adminDashboard' | 'adminEvents' | 'adminModules' | 'adminThemes' | 'adminTimelines' |
